class Solution {
public:
    int smallestUniqueSubarray(vector<int>& nums) {
        int n = nums.size();
        vector<int> sa(n), rank(n), tmp(n);
        iota(sa.begin(), sa.end(), 0);
        vector<int> sorted = nums;
        sort(sorted.begin(), sorted.end());
        sorted.erase(unique(sorted.begin(), sorted.end()), sorted.end());
        for (int i = 0; i < n; ++i)
            rank[i] = lower_bound(sorted.begin(), sorted.end(), nums[i]) - sorted.begin();
        for (int len = 1; len < n; len *= 2) {
            auto cmp = [&](int a, int b) {
                if (rank[a] != rank[b]) return rank[a] < rank[b];
                int x = a + len < n ? rank[a + len] : -1;
                int y = b + len < n ? rank[b + len] : -1;
                return x < y;
            };
            sort(sa.begin(), sa.end(), cmp);
            tmp[sa[0]] = 0;
            for (int i = 1; i < n; ++i)
                tmp[sa[i]] = tmp[sa[i-1]] + cmp(sa[i-1], sa[i]);
            rank.swap(tmp);
            if (rank[sa[n-1]] == n-1) break;
        }
        vector<int> lcp(n, 0);
        int h = 0;
        for (int i = 0; i < n; ++i) {
            int r = rank[i];
            if (r == 0) { h = 0; continue; }
            int j = sa[r-1];
            while (i+h < n && j+h < n && nums[i+h] == nums[j+h]) ++h;
            lcp[r] = h;
            if (h) --h;
        }
        int ans = n;
        for (int r = 0; r < n; ++r) {
            int longest = max(lcp[r], r+1 < n ? lcp[r+1] : 0);
            if (longest < n - sa[r]) ans = min(ans, longest + 1);
        }
        return ans;
    }
};
